extends Node
var p
func _ready() -> void:
	p = get_meta("viento_project")
	call_deferred("_probe")
func _snapshot(label: String, details: Dictionary = {}) -> void:
	var host = p.host.get_ref()
	print("VIENTO_BUDGET_SNAPSHOT:" + JSON.stringify({"label": label, "used": host.execution_budget.snapshot(), "details": details}))
func _probe() -> void:
	var host = p.host.get_ref()
	p.select_animation_clip("59595959-5959-4595-8595-000000000001")
	p.play_animation()
	_sample("reserved")
	host.flush_requests()
	_sample("applied")
	p.pause_animation()
	_sample("pause-reserved")
	host.flush_requests()
	_sample("paused")
func _sample(label: String) -> void:
	var host = p.host.get_ref()
	_snapshot(label, {"reserved": host.animation_control.reserved_count, "sequence": host.animation_control.sequence, "pending": host.animation_control.pending_count()})
